using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Security.Cryptography;using Mono.Cecil;using Mono.Cecil.Cil;
class StagePatch {
 const string Expected="c2da3b5f4d9f2d04e4987442a9cd384c8dbb23fd216fb514b58c1dcaedc6add1", Helper="RTDSettlementDiagnostic";
 static IEnumerable<TypeDefinition> Types(IEnumerable<TypeDefinition> ts){foreach(var t in ts){yield return t;foreach(var n in Types(t.NestedTypes))yield return n;}}
 static string Hash(string p){using(var h=SHA256.Create())return BitConverter.ToString(h.ComputeHash(File.ReadAllBytes(p))).Replace("-","").ToLowerInvariant();}
 static bool Marker(Instruction i){var m=i.Operand as MethodReference;return i.OpCode==OpCodes.Call&&m!=null&&m.DeclaringType.Name==Helper;}
 static string Fingerprint(MethodDefinition m){var all=m.Body.Instructions.ToList();var skip=new HashSet<Instruction>();for(int i=1;i<all.Count;i++)if(Marker(all[i])){if(all[i-1].OpCode!=OpCodes.Ldstr)throw new Exception("Invalid marker");skip.Add(all[i-1]);skip.Add(all[i]);}var kept=all.Where(i=>!skip.Contains(i)).ToList();Func<Instruction,int> pos=i=>{if(i==null)return -1;while(skip.Contains(i))i=i.Next;return kept.IndexOf(i);};Func<object,string> operand=o=>o is Instruction?"@"+pos((Instruction)o):o is Instruction[]?string.Join(",",((Instruction[])o).Select(i=>"@"+pos(i))):Convert.ToString(o);return string.Join("\n",kept.Select(i=>(i.OpCode.OperandType==OperandType.ShortInlineBrTarget?i.OpCode.Name.Substring(0,i.OpCode.Name.Length-2):i.OpCode.Name)+" "+operand(i.Operand)))+"\nEH:"+string.Join(";",m.Body.ExceptionHandlers.Select(e=>e.HandlerType+":"+e.CatchType+":"+pos(e.TryStart)+","+pos(e.TryEnd)+","+pos(e.HandlerStart)+","+pos(e.HandlerEnd)+","+pos(e.FilterStart)));}
 static void Before(MethodDefinition m,Instruction target,string label,MethodReference log){var il=m.Body.GetILProcessor();var a=il.Create(OpCodes.Ldstr,"RTD_SETTLEMENT "+label);var b=il.Create(OpCodes.Call,log);foreach(var i in m.Body.Instructions.ToArray()){if(i.Operand==target)i.Operand=a;var arr=i.Operand as Instruction[];if(arr!=null)for(int k=0;k<arr.Length;k++)if(arr[k]==target)arr[k]=a;}foreach(var e in m.Body.ExceptionHandlers){if(e.TryStart==target)e.TryStart=a;if(e.TryEnd==target)e.TryEnd=a;if(e.HandlerStart==target)e.HandlerStart=a;if(e.HandlerEnd==target)e.HandlerEnd=a;if(e.FilterStart==target)e.FilterStart=a;}il.InsertBefore(target,a);il.InsertBefore(target,b);}
 static void Main(string[] args){if(args.Length!=3)throw new Exception("Usage: StagePatch input.dll output.dll evidence.txt");if(Path.GetFullPath(args[0])==Path.GetFullPath(args[1]))throw new Exception("Refusing in-place write");var a=AssemblyDefinition.ReadAssembly(args[0]);if(a.MainModule.Types.Any(t=>t.Name==Helper))throw new Exception("Already instrumented; refusing duplicate injection");if(Hash(args[0])!=Expected)throw new Exception("Input SHA mismatch");var mod=a.MainModule;var assemblyReferences=mod.AssemblyReferences.Select(r=>r.FullName).ToArray();var unity=mod.AssemblyReferences.First(r=>r.Name=="UnityEngine");var debug=new TypeReference("UnityEngine","Debug",mod,unity);var log=new MethodReference("Log",mod.TypeSystem.Void,debug){HasThis=false};log.Parameters.Add(new ParameterDefinition(mod.TypeSystem.Object));var helper=new TypeDefinition("",Helper,TypeAttributes.NotPublic|TypeAttributes.Abstract|TypeAttributes.Sealed,mod.TypeSystem.Object);mod.Types.Add(helper);var mark=new MethodDefinition("Mark",MethodAttributes.Public|MethodAttributes.Static,mod.TypeSystem.Void);mark.Parameters.Add(new ParameterDefinition(mod.TypeSystem.String));helper.Methods.Add(mark);var p=mark.Body.GetILProcessor();var start=p.Create(OpCodes.Ldarg_0);var end=p.Create(OpCodes.Ret);var handler=p.Create(OpCodes.Pop);p.Append(start);p.Append(p.Create(OpCodes.Call,log));p.Append(p.Create(OpCodes.Leave,end));p.Append(handler);p.Append(p.Create(OpCodes.Leave,end));p.Append(end);mark.Body.ExceptionHandlers.Add(new ExceptionHandler(ExceptionHandlerType.Catch){CatchType=new TypeReference("System","Exception",mod,mod.TypeSystem.Object.Scope),TryStart=start,TryEnd=handler,HandlerStart=handler,HandlerEnd=end});
 var before=new Dictionary<string,string>();var methods=Types(mod.Types).Where(t=>t!=helper).SelectMany(t=>t.Methods).Where(m=>m.HasBody).ToList();int count=0;
 foreach(var m in methods){before[m.FullName]=Fingerprint(m);var original=m.Body.Instructions.ToArray();bool boundary=(m.DeclaringType.Name=="BattleManager"&&m.Name=="QuestClearEvent")||(m.DeclaringType.Name=="SaveDataManager"&&m.Name=="SaveFuncGameRestore")||(m.DeclaringType.Name=="GameManager"&&m.Name=="ClearAssetBundleData")||(m.DeclaringType.Name=="MMResult"&&(m.Name=="Init"||m.Name=="SetupClientData"))||(m.DeclaringType.Name=="ComManager"&&m.Name=="CreateRequest_QuestClear2")||((m.DeclaringType.Name=="Enemy"||m.DeclaringType.Name=="AnimationController")&&m.Name=="UnLoad");if(boundary){Before(m,original[0],m.DeclaringType.Name+"."+m.Name+" ENTER",mark);count++;foreach(var i in original.Where(i=>i.OpCode==OpCodes.Ret)){Before(m,i,m.DeclaringType.Name+"."+m.Name+" EXIT",mark);count++;}}
 foreach(var i in original){var call=i.Operand as MethodReference;if(call==null||(i.OpCode!=OpCodes.Call&&i.OpCode!=OpCodes.Callvirt))continue;bool unload=(call.DeclaringType.FullName=="UnityEngine.AssetBundle"&&call.Name=="Unload")||(call.DeclaringType.FullName=="UnityEngine.Resources"&&call.Name=="UnloadUnusedAssets");bool scene=call.DeclaringType.Name=="SceneManager"&&call.Name=="ChangeScene";if(!unload&&!scene)continue;string tag=m.DeclaringType.Name+"."+m.Name+" IL_"+i.Offset.ToString("x4")+" "+call.DeclaringType.Name+"."+call.Name;Before(m,i,tag+" BEFORE",mark);count++;if(unload&&i.Next!=null){var il=m.Body.GetILProcessor();var after=il.Create(OpCodes.Ldstr,"RTD_SETTLEMENT "+tag+" AFTER");il.InsertAfter(i,after);il.InsertAfter(after,il.Create(OpCodes.Call,mark));count++;}}
 // Widen short branches because marker insertion changes byte distances.
 foreach(var i in m.Body.Instructions){switch(i.OpCode.Code){case Code.Br_S:i.OpCode=OpCodes.Br;break;case Code.Brfalse_S:i.OpCode=OpCodes.Brfalse;break;case Code.Brtrue_S:i.OpCode=OpCodes.Brtrue;break;case Code.Leave_S:i.OpCode=OpCodes.Leave;break;default:if(i.OpCode.OperandType==OperandType.ShortInlineBrTarget){var name=i.OpCode.Name.Substring(0,i.OpCode.Name.Length-2);var f=typeof(OpCodes).GetFields().First(x=>x.FieldType==typeof(OpCode)&&((OpCode)x.GetValue(null)).Name==name);i.OpCode=(OpCode)f.GetValue(null);}break;}}
 }
 foreach(var method in methods)method.Body.MaxStackSize=Math.Max(method.Body.MaxStackSize+1,2);mark.Body.MaxStackSize=1;a.Write(args[1]);var reread=AssemblyDefinition.ReadAssembly(args[1]);if(!assemblyReferences.SequenceEqual(reread.MainModule.AssemblyReferences.Select(r=>r.FullName)))throw new Exception("Assembly references changed");foreach(var m in Types(reread.MainModule.Types).Where(t=>t.Name!=Helper).SelectMany(t=>t.Methods).Where(m=>m.HasBody))if(before[m.FullName]!=Fingerprint(m))throw new Exception("Roundtrip semantic structure mismatch: "+m.FullName);File.WriteAllText(args[2],"Input SHA256: "+Expected+"\nOutput SHA256: "+Hash(args[1])+"\nMarker sites: "+count+"\nVerified all original method opcode/operand sequences, normalized branch targets and exception boundaries after stripping marker pairs.\nAssemblyReferences sequence unchanged; helper Exception uses original corelib scope. Cecil recomputes maxstack on write; original method maxstack reserve increased by one before write.\nNo APK generated or deployed. Runtime/native behavior unverified.\n");Console.WriteLine("Verified marker sites: "+count);
 }
}
